import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import { currentLocation, type GeoLocation } from '../utils/geolocation'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface locateButtonLogicValues {
  error: string | null
  locating: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface locateButtonLogicActions {
  locate: (onLocated: (location: GeoLocation) => void) => {
    onLocated: (location: GeoLocation) => void
  }
  locateFailure: (error: string) => {
    error: string
  }
  locateSuccess: () => {
    value: true
  }
}

export type locateButtonLogicType = MakeLogicType<locateButtonLogicValues, locateButtonLogicActions>

// The locate button next to a scene's latitude/longitude fields
// (LocateButton): asks the browser where it is and hands the answer to the
// form that drew the button. One at a time: the browser has one location.
export const locateButtonLogic = kea<locateButtonLogicType>([
  path(['src', 'components', 'locateButtonLogic']),
  actions({
    locate: (onLocated: (location: GeoLocation) => void) => ({ onLocated }),
    locateSuccess: true,
    locateFailure: (error: string) => ({ error }),
  }),
  reducers({
    locating: [
      false,
      {
        locate: () => true,
        locateSuccess: () => false,
        locateFailure: () => false,
      },
    ],
    error: [
      null as string | null,
      {
        locate: () => null,
        locateSuccess: () => null,
        locateFailure: (_, { error }) => error,
      },
    ],
  }),
  listeners(({ actions }) => ({
    locate: async ({ onLocated }) => {
      try {
        const location = await currentLocation()
        onLocated(location)
        actions.locateSuccess()
      } catch (error) {
        actions.locateFailure(error instanceof Error ? error.message : String(error))
      }
    },
  })),
])
